            var preview=UnityEngine.Object.FindObjectOfType<ContentPreview>();preview.Initialize();var client=preview.GetComponent<PythonStateClient>();var flags=BindingFlags.Instance|BindingFlags.NonPublic;typeof(PythonStateClient).GetField("preview",flags).SetValue(client,preview);var pending=typeof(PythonStateClient).GetField("pending",flags);
            var state=PythonServiceSetup.Sample();state.instance_id="directory-review";state.can_set_shifts=true;state.customer_directory=new PythonCustomerDirectory{today_label="1日目（月）",tomorrow_label="2日目（火）",notes="予定は営業した場合の時点です。休業日は来店しません。",rows=new[]{
