            string unchanged=JsonUtility.ToJson(state);p.close.onClick.Invoke();Check(menu.panel.activeSelf && menu.SelectedGroup==3 && !p.panel.activeSelf,"Menu return");Check(JsonUtility.ToJson(state)==unchanged && pending.GetValue(client)==null,"Viewing changed state");p.Open();pending.SetValue(client,new PythonShiftCommand{kind="save_game"});preview.RefreshPythonControls();p.FilterBy(2);Check(p.Filter==0 && !p.tabs[0].interactable,"Busy guard");pending.SetValue(client,null);apply();p.Disconnect();p.FilterBy(2);Check(p.Filter==0 && !p.sort.interactable && p.notice.text.Contains("未接続"),"Offline guard");
            apply();p.FilterBy(1);state.customer_directory.rows[1].planned_tomorrow=false;apply();Check(p.VisibleCount==0 && p.details.text.Contains("該当"),"Empty filtered list");p.FilterBy(0);state.customer_directory.rows[0].presentation_version=0;state.customer_directory.rows[0].details="旧接続の詳細";p.Select("one");Check(p.details.text.Contains("旧接続の詳細"),"Legacy fallback");state.instance_id="loaded";apply();Check(!p.panel.activeSelf && p.Filter==0 && p.Section==0,"Loaded view reset");Check(pending.GetValue(client)==null,"Read only command guard");
            Debug.Log("CAT_CAFE_CUSTOMER_REVIEW_OK: legacy regression / schedule filters / attention / sections / cat comparison / long text / polling / menu return / busy / offline / empty / load / read only");
